_SAMPLING_EPS = 1e-6
_SAMPLING_VECTOR_ELEMENTS = 4


def _allocate_sampling_rows(
    rows: int,
    vocab_size: int,
    *,
    dtype: torch.dtype,
    device: torch.device,
) -> torch.Tensor:
    """Allocate logical rows with a stride safe for 16-byte vector loads."""

    row_stride = (
        (vocab_size + _SAMPLING_VECTOR_ELEMENTS - 1)
        // _SAMPLING_VECTOR_ELEMENTS
        * _SAMPLING_VECTOR_ELEMENTS
    )
    return torch.empty_strided(
        (rows, vocab_size),
        (row_stride, 1),
        dtype=dtype,
        device=device,
    )


def _sampling_vector_rows(probs: torch.Tensor) -> torch.Tensor:
    rows, vocab_size = int(probs.shape[0]), int(probs.shape[1])
    if probs.dtype == torch.float32:
        if (
            probs.stride(-1) == 1
            and probs.data_ptr() % 16 == 0
            and (rows <= 1 or probs.stride(0) % _SAMPLING_VECTOR_ELEMENTS == 0)
        ):
            return probs
    aligned = _allocate_sampling_rows(
        rows,
        vocab_size,
        dtype=torch.float32,
        device=probs.device,
    )
    aligned.copy_(probs)
    return aligned


@dataclass(frozen=True)
class GreedyTailWorkspace:
    """Persistent zero-initialized completion state for greedy-tail launches."""

    winner_keys: torch.Tensor
    completion_counters: torch.Tensor
    _native_arch: str | None = None
    _native_portable: bool = False
    _native_ampere_target: AmpereGreedyTailTarget | None = None
    _dispatches: dict[tuple[int, int, int, bool], Callable] = field(
        default_factory=dict,
        compare=False,
        repr=False,
    )


def allocate_greedy_tail_workspace(
    capacity: int,
    *,
    device: torch.device | str,
) -> GreedyTailWorkspace:
    if capacity <= 0:
        raise ValueError("greedy-tail workspace capacity must be positive")
    winner_keys = torch.zeros(capacity, dtype=torch.long, device=device)
    completion_counters = torch.zeros(
        capacity, dtype=torch.int32, device=device
    )
    native_arch = None
    native_portable = False
    native_ampere_target = None
    if winner_keys.is_cuda:
        properties = torch.cuda.get_device_properties(winner_keys.device)
        capability = (properties.major, properties.minor)
        ampere_target = ampere_greedy_tail_target_for_device(
            properties.name,
            capability,
            properties.multi_processor_count,
        )
        if ampere_target is not None:
            native_arch = ampere_target.architecture
            native_ampere_target = ampere_target
        elif capability == (9, 0):
            native_arch = "sm90"
        elif capability == (10, 0) and properties.name == "NVIDIA B200":
            native_arch = "sm100"
        elif capability[0] >= 8:
            native_arch = f"sm{capability[0]}{capability[1]}"
            native_portable = True
    return GreedyTailWorkspace(
        winner_keys=winner_keys,
        completion_counters=completion_counters,
        _native_arch=native_arch,
        _native_portable=native_portable,
        _native_ampere_target=native_ampere_target,
    )


def _ampere_greedy_tail_config_for_batch(
    batch: int,
    target: AmpereGreedyTailTarget,
    *,
    vocab_size: int = GREEDY_TAIL_VOCAB_SIZE,
    required: bool,
) -> GreedyTailConfig | None:
    if vocab_size == GREEDY_TAIL_VOCAB_SIZE:
        try:
            return _load_ampere_greedy_tail_config(batch, target)
        except AmpereGreedyTailCalibrationUnavailable:
            if required:
                raise
    else:
        try:
            scoped = _load_ampere_scope_config(batch, vocab_size, target)
        except AmpereGreedyTailCalibrationUnavailable:
            scoped = None
        if scoped is not None:
            return scoped
    if required:
        raise AmpereGreedyTailCalibrationUnavailable(
            f"missing generated Ampere greedy-tail authority for "
            f"vocab={vocab_size}, batch={batch}, target={target.key}"
        )
    return None


def _softmax_greedy_variant_key(vocab_size: int, dtype: torch.dtype) -> str:
    dtype_name = "bfloat16" if dtype == torch.bfloat16 else "float32"
    return _softmax_greedy_variant_key_for_dtype_name(vocab_size, dtype_name)


def _ensure_sampling_variant(
    family: CubinFamily,
    variant_key: str,
    x: torch.Tensor,
    *,
    vocab_size: int,
    logprobs: bool,
) -> bool:
    if family.is_available(variant_key):
        return True
    device_index = int(x.device.index or 0)
    if (variant_key, device_index) in family._handles:
        return True
    if not _ENABLE_JIT:
        return False
    compile_factory = (
        _cubin_bundles._compile_sampling_logprobs
        if logprobs
        else _cubin_bundles._compile_sampling
    )
    _cubin_bundles.jit_compile_and_install(
        family=family,
        variant_key=variant_key,
        compile_fn=compile_factory(
            vocab_size=vocab_size,
            num_threads=_SAMPLING_THREADS[vocab_size],
            max_rounds=_MAX_REJECTION_ROUNDS,
        ),
        block_x=_SAMPLING_THREADS[vocab_size],
        device_index=device_index,
    )
    return True


