def _resolve_greedy_tail_dispatch(
    logits: torch.Tensor,
    workspace: GreedyTailWorkspace,
    config: GreedyTailConfig,
    variant_key: str,
    *,
    require_packed: bool,
) -> Callable | None:
    active_batch = int(logits.shape[0])
    cache_key = (
        config.vocab_size,
        config.batch_capacity,
        active_batch,
        require_packed,
    )
    cached = workspace._dispatches.get(cache_key)
    if cached is not None:
        return cached
    if not _ensure_greedy_tail_variant(
        variant_key,
        logits,
        config=config,
        require_packed=require_packed,
    ):
        return None
    resolve_dispatch = (
        _softmax_greedy_family.resolve_shipped_dispatch
        if require_packed
        else _softmax_greedy_family.resolve_dispatch
    )
    dispatch = resolve_dispatch(
        logits,
        variant_key=variant_key,
        grid_x=active_batch * config.num_splits,
    )
    workspace._dispatches[cache_key] = dispatch
    return dispatch


def _torch_apply_logits_constraints_(
    logits: torch.Tensor,
    constraints: torch.Tensor,
) -> torch.Tensor:
    vocab = int(logits.shape[1])
    for row, plan in enumerate(constraints.cpu()):
        flags = int(plan[0])
        ranges = []
        if flags & 1:
            for range_index in range(3):
                start = max(0, min(vocab, int(plan[2 + 2 * range_index])))
                end = max(0, min(vocab, int(plan[3 + 2 * range_index])))
                if start < end:
                    ranges.append((start, end))
        split = max(0, min(vocab, int(plan[1])))
        if flags == 0:
            continue
        scores = logits[row].clone()
        for start, end in ranges:
            scores[start:end] = -float("inf")
        suppress_prefix = False
        if flags & 2 and 0 < split < vocab:
            tail_mass = torch.logsumexp(scores[split:].float(), dim=0)
            prefix_max = torch.max(scores[:split].float())
            suppress_prefix = bool((tail_mass > prefix_max).item())
        for start, end in ranges:
            logits[row, start:end] = -float("inf")
        if suppress_prefix:
            logits[row, :split] = -float("inf")
    return logits


def _torch_apply_token_mask_and_repetition_(
    logits: torch.Tensor,
    allowed_tokens: torch.Tensor,
    seen_tokens: torch.Tensor,
    repetition_penalties: torch.Tensor,
    row_ids: torch.Tensor,
) -> torch.Tensor:
    active_seen = seen_tokens.index_select(0, row_ids).bool()
    penalties = repetition_penalties.index_select(0, row_ids).unsqueeze(1)
    penalized = torch.where(logits < 0, logits * penalties, logits / penalties)
    logits.copy_(torch.where(active_seen, penalized, logits))
    logits.masked_fill_(allowed_tokens.unsqueeze(0) == 0, -float("inf"))
    return logits


def _torch_constrained_argmax(
    logits: torch.Tensor,
    constraints: torch.Tensor,
    out: torch.Tensor,
) -> torch.Tensor:
    for row, plan in enumerate(constraints.cpu()):
        flags = int(plan[0])
        scores = logits[row].clone()
        if flags & 1:
            for range_index in range(3):
                start = max(
                    0,
                    min(int(logits.shape[1]), int(plan[2 + 2 * range_index])),
                )
                end = max(
                    0,
                    min(int(logits.shape[1]), int(plan[3 + 2 * range_index])),
                )
                if start < end:
                    scores[start:end] = -float("inf")
        split = max(0, min(int(logits.shape[1]), int(plan[1])))
        if flags & 2:
            if 0 < split < int(logits.shape[1]):
                tail_mass = torch.logsumexp(scores[split:].float(), dim=0)
                prefix_max = torch.max(scores[:split].float())
                if tail_mass > prefix_max:
                    scores[:split] = -float("inf")
        out[row] = torch.argmax(scores)
    return out


def constrained_argmax_from_logits(
    logits: torch.Tensor,
    constraints: torch.Tensor,
    *,
    out: torch.Tensor | None = None,
    require_native: bool = False,
    require_packed: bool = False,
) -> torch.Tensor:
    """Greedy selection with generic range and partition constraints.

    Constraint rows are ``[flags, split, start0, end0, start1, end1,
    start2, end2]``. Bit 0 applies the half-open suppression ranges. Bit 1
    selects the tail partition when its log-sum-exp exceeds the prefix max.
    An all-zero row is an ordinary unconstrained argmax. Range endpoints and
    the partition split are clamped to the vocabulary; reversed ranges are
    empty and boundary splits retain ordinary constrained argmax semantics.
    """

    if logits.ndim != 2 or logits.dtype != torch.bfloat16:
        raise ValueError("constrained argmax requires bfloat16 [batch, vocab] logits")
    if logits.stride(-1) != 1:
        raise ValueError("constrained argmax requires contiguous logits rows")
    batch, vocab_size = map(int, logits.shape)
    if (
        constraints.ndim != 2
        or tuple(constraints.shape) != (batch, CONSTRAINT_PLAN_WIDTH)
        or constraints.dtype != torch.int32
        or not constraints.is_contiguous()
        or constraints.device != logits.device
    ):
        raise ValueError(
            f"constraints must be contiguous int32 [{batch}, "
            f"{CONSTRAINT_PLAN_WIDTH}] on the logits device"
        )
    if out is None:
        out = torch.empty((batch,), dtype=torch.long, device=logits.device)
    elif (
        out.ndim != 1
        or int(out.shape[0]) < batch
        or out.dtype != torch.long
        or out.device != logits.device
        or not out.is_contiguous()
    ):
        raise ValueError(
            "out must be a contiguous int64 tensor on the logits device with "
            "at least batch elements"
        )
    out_view = out[:batch]
    if batch == 0:
        return out_view

    variant_key = _constrained_argmax_variant_key(vocab_size)
    if (
        logits.is_cuda
        and vocab_size in _CONSTRAINED_ARGMAX_CONFIGS
        and _ensure_constrained_argmax_variant(
            variant_key,
            logits,
            vocab_size=vocab_size,
            require_packed=require_packed,
        )
    ):
        try:
            resolve_dispatch = (
                _softmax_greedy_family.resolve_shipped_dispatch
                if require_packed
                else _softmax_greedy_family.resolve_dispatch
            )
            dispatch = resolve_dispatch(
                logits,
                variant_key=variant_key,
                grid_x=batch,
            )
            dispatch(out_view, logits, constraints)
            return out_view
        except Exception:
            if require_native or require_packed:
                raise
            warn_fallback_once(
                "constrained_argmax_runtime_error",
                "kestrel-kernels: constrained argmax failed at runtime; using "
                "the PyTorch development fallback.",
            )
    elif require_native or require_packed:
        raise RuntimeError(
            "required packed/native constrained argmax artifact did not resolve "
            f"for vocab={vocab_size}"
        )
    return _torch_constrained_argmax(logits, constraints, out_view)


def apply_logits_constraints_(
    logits: torch.Tensor,
    constraints: torch.Tensor,
    *,
    require_native: bool = False,
    require_packed: bool = False,
) -> torch.Tensor:
    """Apply generic range/partition plans to batched logits in place.

    Range endpoints and the partition split are clamped to the current row's
    vocabulary bounds. Reversed or empty ranges suppress nothing. These are
    the native kernel's memory-safe semantics too, so malformed device plans
    never require a host synchronization merely to align backend behavior.
    """

    if logits.ndim != 2 or logits.dtype != torch.bfloat16:
        raise ValueError(
            "in-place logits constraints require bfloat16 [batch, vocab] logits"
        )
    if logits.stride(-1) != 1:
        raise ValueError("in-place logits constraints require contiguous logits rows")
    batch, vocab_size = map(int, logits.shape)
    if (
        constraints.ndim != 2
        or tuple(constraints.shape) != (batch, CONSTRAINT_PLAN_WIDTH)
        or constraints.dtype != torch.int32
        or not constraints.is_contiguous()
        or constraints.device != logits.device
    ):
        raise ValueError(
            f"constraints must be contiguous int32 [{batch}, "
            f"{CONSTRAINT_PLAN_WIDTH}] on the logits device"
        )
    if batch == 0:
        return logits

    variant_key = _logits_constraints_variant_key(vocab_size)
    if logits.is_cuda and vocab_size in _LOGITS_CONSTRAINT_CONFIGS:
        try:
            available = require_packed or _ensure_logits_constraints_variant(
                variant_key,
                logits,
                vocab_size=vocab_size,
            )
            if available:
                resolve_dispatch = (
                    _softmax_greedy_family.resolve_shipped_dispatch
                    if require_packed
                    else _softmax_greedy_family.resolve_dispatch
                )
                dispatch = resolve_dispatch(
                    logits,
                    variant_key=variant_key,
                    grid_x=batch,
                )
                dispatch(logits, constraints)
                return logits
        except Exception:
            if require_native or require_packed:
                raise
            warn_fallback_once(
                "logits_constraints_runtime_error",
                "kestrel-kernels: in-place logits constraints failed at runtime; "
                "using the PyTorch development fallback.",
            )
    if require_native or require_packed:
        raise RuntimeError(
            "required packed/native in-place logits constraints artifact did not "
            f"resolve for vocab={vocab_size}"
        )
    return _torch_apply_logits_constraints_(logits, constraints)


def apply_token_mask_and_repetition_(
    logits: torch.Tensor,
    allowed_tokens: torch.Tensor,
    seen_tokens: torch.Tensor,
    repetition_penalties: torch.Tensor,
    row_ids: torch.Tensor,
    *,
    require_native: bool = False,
    require_packed: bool = False,
) -> torch.Tensor:
    """Apply a shared allowed-token mask and indexed repetition penalties.

    ``seen_tokens`` and ``repetition_penalties`` are persistent state rows;
    ``row_ids`` maps each active logits row to its state row. Masks use uint8
    storage so torch and CuTe share one byte-addressed ABI. Row IDs must be in
    bounds and penalties must be finite and positive.
    """

    if logits.ndim != 2 or logits.dtype != torch.bfloat16:
        raise ValueError(
            "in-place token preprocessing requires bfloat16 [batch, vocab] logits"
        )
    if logits.stride(-1) != 1:
        raise ValueError("in-place token preprocessing requires contiguous logits rows")
    batch, vocab_size = map(int, logits.shape)
    state_rows = int(seen_tokens.shape[0]) if seen_tokens.ndim == 2 else -1
    if (
        allowed_tokens.shape != (vocab_size,)
        or allowed_tokens.dtype != torch.uint8
        or not allowed_tokens.is_contiguous()
        or allowed_tokens.device != logits.device
        or seen_tokens.ndim != 2
        or int(seen_tokens.shape[1]) != vocab_size
        or seen_tokens.dtype != torch.uint8
        or seen_tokens.stride(-1) != 1
        or seen_tokens.device != logits.device
        or repetition_penalties.shape != (state_rows,)
        or repetition_penalties.dtype != torch.float32
        or not repetition_penalties.is_contiguous()
        or repetition_penalties.device != logits.device
        or row_ids.shape != (batch,)
        or row_ids.dtype != torch.int64
        or not row_ids.is_contiguous()
        or row_ids.device != logits.device
    ):
        raise ValueError(
            "token masks, penalties, and row IDs have an incompatible shape, "
            "dtype, layout, or device"
        )
    if batch == 0:
        return logits

    variant_key = _token_mask_repetition_variant_key(vocab_size)
    if logits.is_cuda and vocab_size in _TOKEN_MASK_REPETITION_CONFIGS:
        try:
            available = require_packed or _ensure_token_mask_repetition_variant(
                variant_key,
                logits,
                vocab_size=vocab_size,
            )
            if available:
                resolve_dispatch = (
                    _token_preprocess_family.resolve_shipped_dispatch
                    if require_packed
                    else _token_preprocess_family.resolve_dispatch
                )
                dispatch = resolve_dispatch(
                    logits,
                    variant_key=variant_key,
                    grid_x=batch,
                )
                dispatch(
                    logits,
                    allowed_tokens,
                    seen_tokens,
                    repetition_penalties,
                    row_ids,
                )
                return logits
        except Exception:
            if require_native or require_packed:
                raise
            warn_fallback_once(
                "token_mask_repetition_runtime_error",
                "kestrel-kernels: token mask/repetition preprocessing failed at "
                "runtime; using the PyTorch development fallback.",
            )
    if require_native or require_packed:
        raise RuntimeError(
            "required packed/native token mask/repetition artifact did not "
            f"resolve for vocab={vocab_size}"
        )
    return _torch_apply_token_mask_and_repetition_(
        logits,
        allowed_tokens,
        seen_tokens,
        repetition_penalties,
        row_ids,
    )


def greedy_logprobs_from_logits(
    logits: torch.Tensor,
    *,
    out: torch.Tensor | None = None,
    logprobs_out: torch.Tensor | None = None,
    require_packed: bool = False,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Return argmax token IDs and untempered model log-probabilities."""

    if logits.ndim != 2:
        raise ValueError(f"logits must be 2D [batch, vocab], got {logits.shape}")
    batch, vocab_size = map(int, logits.shape)
    if out is None:
        out = torch.empty(batch, dtype=torch.int64, device=logits.device)
    if logprobs_out is None:
        logprobs_out = torch.empty(batch, dtype=torch.float32, device=logits.device)
    if (
        out.shape != (batch,)
        or out.dtype != torch.int64
        or out.device != logits.device
        or not out.is_contiguous()
    ):
        raise ValueError("out must be contiguous int64 [batch] on the logits device")
    _validate_logprobs_out(logprobs_out, batch=batch, device=logits.device)
    if batch == 0:
        return out, logprobs_out

    logits_dtype = "bfloat16" if logits.dtype == torch.bfloat16 else "float32"
    variant_key = _greedy_logprobs_variant_key_for_dtype_name(
        vocab_size, logits_dtype
    )
    supported = (
        logits.is_cuda
        and logits.dtype in _SOFTMAX_GREEDY_LOGITS_DTYPES
        and logits.stride(-1) == 1
        and (vocab_size, logits_dtype) in _GREEDY_LOGPROBS_CONFIGS
    )
    runtime_failed = False
    if supported:
        try:
            available = require_packed or _ensure_greedy_logprobs_variant(
                variant_key,
                logits,
                vocab_size=vocab_size,
            )
            if available:
                resolve_dispatch = (
                    _softmax_greedy_family.resolve_shipped_dispatch
                    if require_packed
                    else _softmax_greedy_family.resolve_dispatch
                )
                dispatch = resolve_dispatch(
                    logits,
                    variant_key=variant_key,
                    grid_x=batch,
                )
                dispatch(out, logprobs_out, logits)
                return out, logprobs_out
        except Exception as error:  # pragma: no cover - defensive
            if require_packed:
                raise
            warn_fallback_once(
                "greedy_logprobs_runtime_error",
                "kestrel-kernels: greedy-logprobs cubin failed at runtime; "
                f"falling back to torch. error={type(error).__name__}: {error}",
            )
            runtime_failed = True
    if require_packed:
        raise RuntimeError(
            "required packed greedy-logprobs artifact did not resolve for "
            f"vocab={vocab_size}"
        )
    if logits.is_cuda and not runtime_failed:
        warn_fallback_once(
            "greedy_logprobs_unavailable",
            "kestrel-kernels: using PyTorch fallback for "
            "greedy_logprobs_from_logits.",
        )

    torch.argmax(logits, dim=-1, out=out)
    scores = logits.to(dtype=torch.float32)
    selected = scores.gather(1, out.unsqueeze(1)).squeeze(1)
    logprobs_out.copy_(selected - torch.logsumexp(scores, dim=1))
    return out, logprobs_out


def _torch_greedy_tail(
    logits: torch.Tensor,
    batch_indices: torch.Tensor,
    pending_token_ids: torch.Tensor,
    out: torch.Tensor,
    *,
    batch_indices_in_bounds: bool,
) -> torch.Tensor:
    torch.argmax(logits, dim=-1, out=out)
    # Tried per-step bounds masking on B200 Gemma B4: 77.54-77.86 us versus
    # 16.38 us for direct index_copy_; keep it only for the safe default.
    if batch_indices_in_bounds:
        pending_token_ids.index_copy_(0, batch_indices, out)
    else:
        valid = (batch_indices >= 0) & (batch_indices < pending_token_ids.shape[0])
        pending_token_ids.index_copy_(0, batch_indices[valid], out[valid])
    return out


def greedy_tail_from_logits(
    logits: torch.Tensor,
    batch_indices: torch.Tensor,
    pending_token_ids: torch.Tensor,
    workspace: GreedyTailWorkspace,
    *,
    out: torch.Tensor | None = None,
    require_native: bool = False,
    require_packed: bool = False,
    batch_indices_in_bounds: bool = False,
) -> torch.Tensor:
    """Select greedy BF16 tokens and publish scheduler pending-token state.

    Calibrated Ampere, Hopper, and B200 GPUs use one multi-CTA launch. Other devices
    and unsupported shapes execute the equivalent torch argmax plus index-copy
    chain. ``workspace``
    must come from :func:`allocate_greedy_tail_workspace`; the native kernel
    resets its completion state before each same-stream launch returns. Rows
    whose pending-token index is outside the destination are sampled into
    ``out`` but do not update ``pending_token_ids`` on any backend. Callers
    that already prove every active index is in bounds may set
    ``batch_indices_in_bounds`` to avoid the fallback path's device-to-host
    synchronization for boolean indexing.
    """

    if logits.ndim != 2:
        raise ValueError("greedy tail requires [batch, vocab] logits")
    batch, vocab_size = map(int, logits.shape)
    if (
        batch_indices.ndim != 1
        or int(batch_indices.shape[0]) < batch
        or batch_indices.dtype != torch.long
        or batch_indices.device != logits.device
        or not batch_indices.is_contiguous()
    ):
        raise ValueError(
            "batch_indices must be contiguous int64 on the logits device with "
            "at least batch elements"
        )
    if (
        pending_token_ids.ndim != 1
        or pending_token_ids.dtype != torch.long
        or pending_token_ids.device != logits.device
        or not pending_token_ids.is_contiguous()
    ):
        raise ValueError(
            "pending_token_ids must be contiguous int64 on the logits device"
        )
    if not isinstance(workspace, GreedyTailWorkspace):
        raise TypeError("workspace must be a GreedyTailWorkspace")
    winner_keys = workspace.winner_keys
    completion_counters = workspace.completion_counters
    if (
        winner_keys.ndim != 1
        or int(winner_keys.shape[0]) < batch
        or winner_keys.dtype != torch.long
        or winner_keys.device != logits.device
        or not winner_keys.is_contiguous()
    ):
        raise ValueError(
            "workspace winner_keys must be contiguous int64 on the logits "
            "device with at least batch elements"
        )
    if (
        completion_counters.ndim != 1
        or int(completion_counters.shape[0]) < batch
        or completion_counters.dtype != torch.int32
        or completion_counters.device != logits.device
        or not completion_counters.is_contiguous()
    ):
        raise ValueError(
            "workspace completion_counters must be contiguous int32 on the "
            "logits device with at least batch elements"
        )
    if out is None:
        out = torch.empty((batch,), dtype=torch.long, device=logits.device)
    elif (
        out.ndim != 1
        or int(out.shape[0]) < batch
        or out.dtype != torch.long
        or out.device != logits.device
        or not out.is_contiguous()
    ):
        raise ValueError(
            "out must be contiguous int64 on the logits device with at least "
            "batch elements"
        )
    out_view = out[:batch]
    if batch == 0:
        return out_view
    batch_indices_view = batch_indices[:batch]
    native_cuda_input = (
        logits.is_cuda
        and logits.dtype == torch.bfloat16
        and logits.is_contiguous()
        and workspace._native_arch is not None
    )
    if native_cuda_input:
        if workspace._native_ampere_target is not None:
            config = _ampere_greedy_tail_config_for_batch(
                batch,
                workspace._native_ampere_target,
                vocab_size=vocab_size,
                required=require_native or require_packed,
            )
            variant_key_fn = lambda vocab, capacity: (
                _ampere_greedy_tail_variant_key(
                    vocab,
                    capacity,
                    workspace._native_ampere_target.key,
                )
            )
            if require_packed:
                if vocab_size == GREEDY_TAIL_VOCAB_SIZE:
                    validate_ampere_greedy_tail_shipping_sources(
                        workspace._native_ampere_target
                    )
                else:
                    validate_ampere_greedy_tail_scope_shipping_sources(
                        workspace._native_ampere_target
                    )
        elif workspace._native_arch == "sm90":
            config = h100_greedy_tail_config_for_batch(batch)
            variant_key_fn = _h100_greedy_tail_variant_key
            if require_packed:
                validate_h100_greedy_tail_shipping_sources()
        elif workspace._native_arch == "sm100" and not workspace._native_portable:
            config = greedy_tail_config_for_batch(batch)
            variant_key_fn = _greedy_tail_variant_key
            if require_packed:
                validate_greedy_tail_shipping_sources()
        else:
            config = (
                GreedyTailConfig(batch, vocab_size, PORTABLE_GREEDY_TAIL_THREADS,
                                 PORTABLE_GREEDY_TAIL_SPLITS)
                if vocab_size in _SUPPORTED_VOCAB_SIZES and vocab_size % 8 == 0
                else None
            )
            variant_key_fn = None
        if config is not None and vocab_size == config.vocab_size:
            try:
                variant_key = (
                    portable_greedy_tail_variant_key(config.vocab_size)
                    if variant_key_fn is None else variant_key_fn(
                        config.vocab_size, config.batch_capacity)
                )
                dispatch = _resolve_greedy_tail_dispatch(
                    logits,
                    workspace,
                    config,
                    variant_key,
                    require_packed=require_packed,
                )
                if dispatch is None:
                    raise RuntimeError("native greedy-tail variant is unavailable")
                dispatch(
                    out_view,
                    pending_token_ids,
                    logits,
                    batch_indices_view,
                    winner_keys[:batch],
                    completion_counters[:batch],
                )
                return out_view
            except Exception:
                if require_native or require_packed:
                    raise
                warn_fallback_once(
                    "greedy_tail_runtime_error",
                    "kestrel-kernels: greedy tail failed at runtime; using the "
                    "equivalent PyTorch fallback path.",
                )
        elif require_native or require_packed:
            raise RuntimeError(
                "required packed/native greedy-tail artifact did not resolve for "
                f"batch={batch}, vocab={vocab_size}"
            )
    elif require_native or require_packed:
        raise RuntimeError(
            "required packed/native greedy-tail artifact did not resolve for "
            f"batch={batch}, vocab={vocab_size}"
        )
    if logits.is_cuda:
        # Measured sm86 B1/vocab151936 torch at 11.26 us hot / 15.14 us cold:
        # zero-cost replacement is <0.3% of Qwen-ASR 1.7B; keeping fallback.
        warn_fallback_once(
            "greedy_tail_cuda_unavailable",
            "kestrel-kernels: native CUDA greedy tail is unavailable; using "
            "the equivalent PyTorch fallback path.",
        )
    return _torch_greedy_tail(
        logits,
        batch_indices_view,
        pending_token_ids,
        out_view,
        batch_indices_in_bounds=batch_indices_in_bounds,
    )


def top_p_sampling_from_probs(
    probs: torch.Tensor,
    top_p: torch.Tensor,
    *,
    generator: torch.Generator | None = None,
    logprobs_out: torch.Tensor | None = None,
    require_packed: bool = False,
) -> torch.Tensor:
    """Sample token IDs from probabilities and per-row top-p thresholds."""
    if probs.ndim != 2:
        raise ValueError(f"probs must be 2D [batch, vocab], got shape {tuple(probs.shape)}")
    if probs.shape[0] == 0:
        return probs.new_empty((0,), dtype=torch.long)
    if probs.dtype not in (torch.float16, torch.bfloat16, torch.float32):
        raise ValueError(f"unsupported probs dtype {probs.dtype}; expected fp16/bf16/fp32")
    if top_p.ndim == 2 and top_p.shape[1] == 1:
        top_p = top_p.view(-1)
    if top_p.ndim != 1:
        raise ValueError(f"top_p must be 1D [batch], got shape {tuple(top_p.shape)}")
    if top_p.shape[0] != probs.shape[0]:
        raise ValueError(
            f"top_p batch dimension ({top_p.shape[0]}) must match probs ({probs.shape[0]})"
        )
    if logprobs_out is not None:
        _validate_logprobs_out(logprobs_out, batch=probs.shape[0], device=probs.device)

    vocab_size = int(probs.shape[1])
    family = _logprobs_family if logprobs_out is not None else _family
    variant_key = f"vocab_{vocab_size}"

    supported = (
        probs.device.type == "cuda" and vocab_size in _SUPPORTED_VOCAB_SIZES
    )
    available = supported and (
        require_packed
        or _ensure_sampling_variant(
            family,
            variant_key,
            probs,
            vocab_size=vocab_size,
            logprobs=logprobs_out is not None,
        )
    )
    if available:
        try:
            return _run_cubin_kernel(
                probs=probs,
                top_p=top_p,
                generator=generator,
                logprobs_out=logprobs_out,
                require_packed=require_packed,
            )
        except Exception as e:
            if require_packed:
                raise
            warn_fallback_once(
                f"{_KERNEL_KEY}_runtime_error",
                "kestrel-kernels: CuTe top-p kernel failed at runtime; "
                f"falling back to PyTorch. error={type(e).__name__}: {e}",
            )

    if require_packed:
        raise RuntimeError(
            "required packed top-p sampling artifact did not resolve for "
            f"vocab={vocab_size}"
        )

    return warn_and_run_fallback(
        kernel_key=_KERNEL_KEY,
        message="kestrel-kernels: using PyTorch fallback for top_p_sampling_from_probs.",
        fallback=top_p_sampling_torch,
        kwargs={
            "probs": probs,
            "top_p": top_p,
            "generator": generator,
            "logprobs_out": logprobs_out,
        },
    )


def sample_step_from_logits(
    logits: torch.Tensor,
    temperatures: torch.Tensor,
    top_p: torch.Tensor,
    *,
    out: torch.Tensor | None = None,
    generator: torch.Generator | None = None,
    logprobs_out: torch.Tensor | None = None,
    require_packed: bool = False,
) -> torch.Tensor:
    """Sample token IDs from raw logits — auto-dispatch by device.

    Behaviour:
      - clamp ``temperatures ≥ 0`` and ``top_p ∈ [eps, 1.0]``
      - rows with ``temp ≤ eps`` OR non-finite probs are forced to
        argmax (greedy override)
      - otherwise sample from the temperature-scaled softmax
        truncated at ``top_p``

    On MPS this is one fused Metal dispatch (~5× the torch chain).
    On CUDA this is the existing chain that wraps the cubin sampler.
    ``require_packed`` makes both CUDA launches packed-only and fail-closed.
    """
    if logits.ndim != 2:
        raise ValueError(f"logits must be 2D [batch, vocab], got shape {tuple(logits.shape)}")
    batch = logits.shape[0]
    if temperatures.shape[0] != batch or top_p.shape[0] != batch:
        raise ValueError("Sampling parameters must match logits batch dimension")
    if logprobs_out is not None:
        _validate_logprobs_out(logprobs_out, batch=batch, device=logits.device)

    if logits.device.type == "mps":
        if require_packed:
            raise RuntimeError("packed CUDA sampling was required for an MPS tensor")
        # Lazy import — non-Mac wheels don't ship this module.
        from kestrel_kernels.mps.sampling import sample_step_from_logits_mps

        return sample_step_from_logits_mps(
            logits,
            temperatures,
            top_p,
            out=out,
            generator=generator,
            logprobs_out=logprobs_out,
        )

    # CUDA fast path: fused softmax + greedy override → existing
    # rejection top-p cubin. Replaces the 12-op torch chain with two
    # cubin launches; preserves arbitrary top_p / temperature support
    # and honours ``generator`` (passed through to the cubin sampler).
    # BF16 logits are upcast inside the cubin and accumulated as FP32.
    vocab_size = int(logits.shape[1])
    softmax_greedy_variant_key = _softmax_greedy_variant_key(vocab_size, logits.dtype)
    supported = (
        logits.device.type == "cuda"
        and logits.dtype in _SOFTMAX_GREEDY_LOGITS_DTYPES
        and temperatures.dtype == torch.float32
        and top_p.dtype == torch.float32
        and vocab_size in _SUPPORTED_VOCAB_SIZES
    )
    available = supported and (
        require_packed
        or _ensure_softmax_greedy_variant(
            softmax_greedy_variant_key,
            logits,
            vocab_size=vocab_size,
        )
    )
    if available:
        # Layout precondition checked here (not inside the cubin
        # helper) so the resulting ValueError propagates instead of
        # being swallowed by the catch-and-warn fallback below.
        # The cubin accepts dynamic row stride, but its innermost
        # dimension is compiled with stride 1. Silently copying would
        # mask a perf surprise (the copy is comparable to the kernel
        # itself).
        if logits.stride(-1) != 1:
            raise ValueError(
                "sample_step_from_logits CUDA path requires logits with "
                "innermost stride 1. Got a strided view; materialise with "
                "``logits.contiguous()`` at the call site if intentional."
            )
        if not temperatures.is_contiguous():
            raise ValueError(
                "sample_step_from_logits CUDA path requires contiguous "
                "temperatures."
            )
        try:
            probs = _run_softmax_greedy_cubin(
                logits,
                temperatures,
                require_packed=require_packed,
            )
            topp_clamped = torch.clamp(top_p, min=_SAMPLING_EPS, max=1.0)
            sampled = top_p_sampling_from_probs(
                probs,
                topp_clamped,
                generator=generator,
                logprobs_out=logprobs_out,
                require_packed=require_packed,
            )
            if out is not None:
                out.copy_(sampled)
                return out
            return sampled
        except Exception as e:  # pragma: no cover - defensive
            if require_packed:
                raise
            warn_fallback_once(
                f"{_SOFTMAX_GREEDY_KEY}_runtime_error",
                "kestrel-kernels: softmax_greedy cubin failed at runtime; "
                f"falling back to torch chain. error={type(e).__name__}: {e}",
            )

    if require_packed:
        raise RuntimeError(
            "required packed sampling artifacts did not resolve for "
            f"vocab={vocab_size}"
        )

    return _torch_sample_step(
        logits,
        temperatures,
        top_p,
        out=out,
        generator=generator,
        logprobs_out=logprobs_out,
    )


def _run_softmax_greedy_cubin(
    logits: torch.Tensor,
    temperatures: torch.Tensor,
    *,
    require_packed: bool = False,
) -> torch.Tensor:
    """Invoke the softmax_greedy cubin. Returns a fresh probs tensor.

    Caller (``sample_step_from_logits``) is responsible for the layout
    precondition — the cubin is compiled with innermost stride 1.
    """
    rows, vocab_size = int(logits.shape[0]), int(logits.shape[1])
    probs = _allocate_sampling_rows(
        rows,
        vocab_size,
        dtype=torch.float32,
        device=logits.device,
    )
    resolve_dispatch = (
        _softmax_greedy_family.resolve_shipped_dispatch
        if require_packed
        else _softmax_greedy_family.resolve_dispatch
    )
    dispatch = resolve_dispatch(
        logits,
        variant_key=_softmax_greedy_variant_key(vocab_size, logits.dtype),
        grid_x=rows,
    )
    dispatch(probs, logits, temperatures)
    return probs


def _torch_sample_step(
    logits: torch.Tensor,
    temperatures: torch.Tensor,
    top_p: torch.Tensor,
    *,
    out: torch.Tensor | None = None,
    generator: torch.Generator | None = None,
    logprobs_out: torch.Tensor | None = None,
) -> torch.Tensor:
    """Reference logits → token id chain.

    On CUDA this is the canonical fast path (clamp + softmax +
    cubin top_p sampler under ``top_p_sampling_from_probs``). On
    CPU / other devices it's the torch reference.
    """
    temps = torch.clamp(temperatures, min=0.0)
    topp = torch.clamp(top_p, min=_SAMPLING_EPS, max=1.0)

    greedy_ids = logits.argmax(dim=-1)
    eff_temp = torch.where(
        temps > _SAMPLING_EPS, temps, torch.ones_like(temps)
    ).unsqueeze(-1)
    scaled = logits / eff_temp
    probs = torch.softmax(scaled, dim=-1, dtype=torch.float32)

    row_invalid = ~torch.isfinite(probs).all(dim=-1)
    force_greedy = (temps <= _SAMPLING_EPS) | row_invalid
    probs.nan_to_num_(0.0, posinf=0.0, neginf=0.0)
    probs.masked_fill_(force_greedy.unsqueeze(1), 0.0)
    probs.scatter_add_(
        1, greedy_ids.unsqueeze(1),
        force_greedy.to(probs.dtype).unsqueeze(1),
    )

    sampled = top_p_sampling_from_probs(
        probs,
        topp,
        generator=generator,
        logprobs_out=logprobs_out,
    )
    if out is not None:
        out.copy_(sampled)
        return out
    return sampled


def _run_cubin_kernel(
    *,
    probs: torch.Tensor,
    top_p: torch.Tensor,
    generator: torch.Generator | None,
    logprobs_out: torch.Tensor | None = None,
    require_packed: bool = False,
) -> torch.Tensor:
    probs_f = _sampling_vector_rows(probs)
    top_p_f = torch.clamp(
        top_p.to(device=probs.device, dtype=torch.float32),
        min=1e-6,
        max=1.0,
    ).contiguous()
    rows = int(probs_f.shape[0])
    uniforms = torch.rand(
        (rows, _MAX_REJECTION_ROUNDS),
        device=probs.device,
        dtype=torch.float32,
        generator=generator,
    )
    sampled = torch.empty((rows,), device=probs.device, dtype=torch.long)
    vocab_size = int(probs_f.shape[1])
    family = _logprobs_family if logprobs_out is not None else _family
    resolve_dispatch = (
        family.resolve_shipped_dispatch
        if require_packed
        else family.resolve_dispatch
    )
    dispatch = resolve_dispatch(
        probs_f, variant_key=f"vocab_{vocab_size}", grid_x=rows,
    )
    if logprobs_out is not None:
        dispatch(sampled, probs_f, top_p_f, uniforms, logprobs_out)
    else:
        dispatch(sampled, probs_f, top_p_f, uniforms)
    return sampled


def _validate_logprobs_out(
    logprobs_out: torch.Tensor,
    *,
    batch: int,
    device: torch.device,
) -> None:
    if logprobs_out.ndim != 1 or logprobs_out.shape[0] != batch:
        raise ValueError(
            f"logprobs_out must be 1D [batch={batch}], got shape "
            f"{tuple(logprobs_out.shape)}"
        )
    if logprobs_out.dtype != torch.float32:
        raise ValueError(f"logprobs_out must be float32; got {logprobs_out.dtype}")
    if logprobs_out.device != device:
        raise ValueError("logprobs_out must live on the same device as inputs")
    if not logprobs_out.is_contiguous():
        raise ValueError("logprobs_out must be contiguous")


